const consentRequest=(f:any,e:any,purpose='collection',expectedRevision=0,validity:any={kind:'untilRevoked'})=>({operationId:randomUUID(),expectedRevision,scope:f.consentScope(e,purpose),command:'requestSourceConsent',validity,reviewDeadlineAt:new Date(Date.now()+300000).toISOString()});
const consentApproval=(r:any,reserved:any)=>({operationId:randomUUID(),expectedRevision:r.expectedRevision,scope:r.scope,command:'approveSourceConsent',request:r,confirmationDigest:reserved.confirmationDigest,humanConfirmed:true});
async function approve(f:any,r:any){const reserved=await f.consent('requestApproval',r);assert.equal(reserved.kind,'reserved',JSON.stringify(reserved));const a=consentApproval(r,reserved);assert.equal((await f.consent('approve',a)).kind,'observed');const terminal=await f.consent('reconcile',a);assert.equal(terminal.kind,'terminal',JSON.stringify(terminal));assert.equal(terminal.binding.family,'healthSourceConsent');return {request:r,reserved,approval:a,terminal};}
async function prepared(f:any){const e=await f.enroll();await f.decide(f.mapping());await f.decide(f.retention(e));return e;}

