async function approveDomain(domain:any,r:any,family:string){const reserved=await domain.consent('requestApproval',r);assert.equal(reserved.kind,'reserved',JSON.stringify(reserved));const approval=consentApproval(r,reserved);assert.equal((await domain.consent('reconcile',approval)).reason,'unknown');assert.equal((await domain.consent('approve',approval)).kind,'observed');const terminal=await domain.consent('reconcile',approval);assert.equal(terminal.kind,'terminal');assert.equal(terminal.binding.family,family);return {request:r,approval,terminal};}

