 assert.deepEqual(next.filter(m=>m.id!==85),old);assert.equal(next.find(m=>m.id===85)!.sql,readFileSync(new URL('../../../packages/storage-sqlite/src/migrations/0085_mobile_context_interpretation.sql',import.meta.url),'utf8'));
 const database=new Database({path:':memory:',migrations:next});try{database.migrate();assertMobileSourceControlMigrationInventory(database);assert.throws(()=>assertHealthConsentMigrationInventory(database));assert.throws(()=>assertCalendarMigrationInventory(database,true,true));assert.throws(()=>assertMobileSourceConsentMigrationInventory(database));}finally{database.close();}
