  assert.equal(f.app.server.listening,false);assert(f.app.admin.healthPolicyOwner);assert(f.app.admin.calendarPolicyOwner);let e=await prepared(f);const c=await f.calendar.enroll();await f.calendar.decide(f.calendar.mapping());await f.calendar.decide(f.calendar.retention(c));
