  const cc=await approveDomain(f.calendar,consentRequest(f.calendar,c),'calendarSourceConsent');assert.equal((await f.request('/api/runtime/v1/mobile-context',selected)).status,403);const ct=await approveDomain(f.calendar,consentRequest(f.calendar,c,'transmission'),'calendarSourceConsent');const accepted=await f.request('/api/runtime/v1/mobile-context',selected);assert.equal(accepted.status,200,accepted.body.toString());assert.equal(accepted.json().result.receipts[0].outcome,'accepted');assert.equal(f.checkpoint().records,2);
  const queued=f.change(e),captured=hg.capturePolicy(f.actor(),e)!;assert(captured);e=await f.mobile('configure',{enrollmentId:e.enrollmentId,expectedRevision:e.revision,state:'active',configuration:{...e.configuration,collectionPaused:true}});assert.equal((await f.mobile('ingest',{schemaVersion:'1.0.0',changes:[queued]}))[0].code,'scope');assert.equal(captured.current(captured.binding),false);assert.equal(cg.allowed(f.actor() as any,c,'collect'),true);e=await f.mobile('configure',{enrollmentId:e.enrollmentId,expectedRevision:e.revision,state:'active',configuration:{...e.configuration,collectionPaused:false}});assert.equal(captured.current(captured.binding),false);assert.equal((await f.mobile('ingest',{schemaVersion:'1.0.0',changes:[queued]}))[0].outcome,'accepted');assert.equal(f.checkpoint().records,3);
