   const e=await f.enroll(),journalPath=f.app.admin.recovery.journal.directory+'/journal.json',before=readFileSync(journalPath);if(kind==='stale')f.app.database.connection.exec('UPDATE recovery_source_projection SET epoch=epoch+1');const marker=f.app.database.connection.prepare('SELECT * FROM recovery_source_projection').all();await f.applyLaunchSelection(candidate.sourceProductionLaunchOptions,{mobileSchemaPlan:'mobile-source-consent/1',...selectionData('combined',f.profile)},kind==='missing'?()=>renameSync(journalPath,journalPath+'.retained-original'):undefined);assert.equal(f.app.admin.recovery.journal.sourceCurrent(),false);assert.equal(f.app.admin.healthPolicyOwner!.productionHealthGovernance().allowed(f.actor(),e,'collect'),false);assert.equal((await f.consent('requestApproval',consentRequest(f,e))).kind,'held');assert.deepEqual(f.app.database.connection.prepare('SELECT * FROM recovery_source_projection').all(),marker);if(kind==='missing'){assert.equal(existsSync(journalPath),false);assert.deepEqual(readFileSync(journalPath+'.retained-original'),before);}else assert.deepEqual(readFileSync(journalPath),before);assert.equal(Number(f.app.database.connection.prepare('SELECT count(*) n FROM mobile_context_records').get()!.n),0);
